ty":"high","heartbeat":true,"grace_factor":2.5,"reason":"Ativo em produção (homologação 2026-09-15); Configuration Drift Guardian READ-ONLY"},{"slug":"20-incident-correlation-engine","workflow_id":"A8seV6ObRlSBsNZ9","name":"20 - INCIDENT CORRELATION ENGINE","expected_state":"active","architectural_status":"PRODUCTION","trigger_type":"schedule","expected_interval_minutes":1,"criticality":"high","heartbeat":true,"grace_factor":2.5,"reason":"Ativo em produção (gate 2026-09-15); Incident Correlation Engine READ/ANALYZE/WRITE-incident-state only — sem auto-repair"},{"slug":"21-incident-notification-manager","workflow_id":"7UAfZAfh111UdZXy","name":"21 - INCIDENT NOTIFICATION MANAGER","expected_state":"active","architectural_status":"PRODUCTION","trigger_type":"schedule","expected_interval_minutes":1,"criticality":"high","heartbeat":true,"grace_factor":2.5,"reason":"Ativo em Shadow Mode (gate 2026-09-15); Incident Notification Manager — enforcement=false, auto_suppression=false; sem caminho real de entrega"}]};
const wfResp = $('List n8n Workflows').first().json || {};
const health = $('Get Health Agent').first().json || {};
const meta = $('Get Self Health Meta').first().json || {};
const workflowsOk = Array.isArray(wfResp.data);
const context = {
  registry: REGISTRY,
  workflows: workflowsOk ? wfResp.data : [],
  workflowsOk,
  health,
  meta,
  checked_at: new Date().toISOString(),
  started_ms: Date.now(),
};
const items = [];
for (const w of (REGISTRY.workflows || [])) {
  if (!w.workflow_id) continue; // blocked/docs-only without id
  items.push({ json: { ...context, target: w, workflow_id: w.workflow_id } });
}
if (!items.length) {
  items.push({ json: { ...context, target: null, workflow_id: null, _empty: true } });
}
return items;

const ctx = $('Build Exec Targets').item.json || {};
const body = $json || {};
let executions = [];
if (Array.isArray(body.data)) executions = body.data;
else if (body.data && Array.isArray(body.data.data)) executions = body.data.data;
const forbidden = String(body.message || '').toLowerCase().includes('forbidden') || body.statusCode === 403;
return {
  json: {
    workflow_id: ctx.workflow_id,
    target: ctx.target,
    registry: ctx.registry,
    workflows: ctx.workflows,
    workflowsOk: ctx.workflowsOk,
    health: ctx.health,
    meta: ctx.meta,
    checked_at: ctx.checked_at,
    started_ms: ctx.started_ms,
    executions,
    executions_available: !forbidden,
    exec_error: body.message || null,
  }
};

function severityFor(criticality, event) {
  const crit = (criticality || 'medium').toLowerCase();
  if (event === 'event_bus_unavailable') return 'critical';
  const mapInactive = { critical: 'error', high: 'error', medium: 'warning', low: 'warning' };
  const mapOverdue = { critical: 'error', high: 'error', medium: 'warning', low: 'info' };
  if (event === 'workflow_unexpectedly_inactive') return mapInactive[crit] || 'warning';
  if (event === 'workflow_execution_overdue') return mapOverdue[crit] || 'warning';
  if (event === 'workflow_execution_failed') return mapInactive[crit] || 'warning';
  if (['workflow_recovered','workflow_reactivated','event_bus_recovered'].includes(event)) return 'info';
  return 'warning';
}

const rows = $input.all().map(i => i.json);
const base = rows.find(r => r.registry) || rows[0] || {};
const REGISTRY = base.registry || { workflows: [], defaults: {} };
const defaults = REGISTRY.defaults || {};
const graceDefault = Number(defaults.grace_factor || 2.5);
const failErr = Number(defaults.failure_streak_error || 3);
const workflows = Array.isArray(base.workflows) ? base.workflows : [];
const workflowsOk = !!base.workflowsOk;
const byId = Object.fromEntries(workflows.map(w => [w.id, w]));
const meta = base.meta || {};
const prevFp = meta.last_fingerprints || {};
const health = base.health || {};
const now = new Date(base.checked_at || Date.now());
const checked_at = now.toISOString();
const started_ms = Number(base.started_ms || Date.now());

const execById = {};
let executionsAvailable = true;
for (const r of rows) {
  if (!r.workflow_id) continue;
  if (r.executions_available === false) executionsAvailable = false;
  execById[r.workflow_id] = {
    executions: Array.isArray(r.executions) ? r.executions : [],
    available: r.executions_available !== false,
  };
}

const items = [];
for (const reg of (REGISTRY.workflows || [])) {
  const wid = reg.workflow_id;
  const live = wid ? byId[wid] : null;
  const expected = reg.expected_state;
  const crit = reg.criticality || 'medium';
  const grace = Number(reg.grace_factor || graceDefault);
  const intervalM = reg.expected_interval_minutes;
  const intervalS = (intervalM == null) ? null : Math.round(Number(intervalM) * 60);
  const bucket = wid ? execById[wid] : null;
  const execs = bucket ? bucket.executions : [];
  const latest = execs[0] || null;
  let consec = 0;
  for (const e of execs) {
    if (['error','crashed','failed'].includes(e.status)) consec += 1;
    else break;
  }

  const item = {
    workflow_id: wid,
    workflow_name: reg.name,
    expected_state: expected,
    actual_state: null,
    last_execution_at: latest ? latest.startedAt : null,
    last_execution_status: latest ? latest.status : null,
    expected_interval_seconds: intervalS,
    overdue: false,
    consecutive_failures: consec,
    health_status: 'unknown',
    reason: null,
    event: null,
    severity: null,
    should_emit: false,
    route: 'event_bus',
    fingerprint: null,
    details: {
      trigger_type: reg.trigger_type,
      architectural_status: reg.architectural_status,
      criticality: crit,
      executions_available: bucket ? bucket.available : executionsAvailable,
      known_limitation: !!reg.known_limitation,
    },
  };

  if (expected === 'blocked' || ['BLOCKED_HARDWARE','DOCUMENTATION_ONLY'].includes(reg.architectural_status)) {
    item.actual_state = 'blocked';
    item.health_status = 'blocked_expected';
    item.reason = reg.reason || 'known_limitation';
    item.fingerprint = `${wid || reg.slug}|blocked_expected`;
    items.push(item); continue;
  }

  if (expected === 'inactive') {
    if (live && live.active === true) {
      item.actual_state = 'active';
      item.health_status = 'degraded';
      item.reason = 'unexpectedly_active';
      item.should_emit = false;
      item.fingerprint = `${wid}|unexpectedly_active`;
      items.push(item); continue;
    }
    item.actual_state = 'inactive';
    item.health_status = 'inactive_expected';
    item.reason = reg.reason || 'intentionally_inactive';
    item.fingerprint = `${wid}|inactive_expected`;
    items.push(item); continue;
  }

  if (!workflowsOk) {
    item.health_status = 'unknown';
    item.reason = 'workflow_list_unavailable';
    item.fingerprint = `${wid}|unknown_list`;
    items.push(item); continue;
  }

  if (!live) {
    item.actual_state = 'missing';
    item.health_status = 'failed';
    item.reason = 'workflow_missing';
    item.event = 'workflow_unexpectedly_inactive';
    item.severity = severityFor(crit, item.event);
    item.should_emit = true;
    item.fingerprint = `${wid}|missing`;
    items.push(item); continue;
  }

  if (live.active === false) {
    item.actual_state = 'inactive';
    item.health_status = 'failed';
    item.reason = 'unexpectedly_inactive';
    item.event = (reg.slug === '00-hestia-event-bus') ? 'event_bus_unavailable' : 'workflow_unexpectedly_inactive';
    item.severity = severityFor(crit, item.event);
    item.should_emit = true;
    item.route = (item.event === 'event_bus_unavailable') ? 'break_glass' : 'event_bus';
    item.fingerprint = `${wid}|${item.event}`;
    items.push(item); continue;
  }

  item.actual_state = 'active';

  if (consec >= failErr && latest && ['error','crashed','failed'].includes(latest.status)) {
    item.health_status = 'failed';
    item.reason = 'consecutive_failures';
    item.event = 'workflow_execution_failed';
    item.severity = severityFor(crit, item.event);
    item.should_emit = true;
    item.fingerprint = `${wid}|failed|${consec}`;
    items.push(item); continue;
  }

  if (reg.heartbeat && reg.trigger_type === 'schedule' && intervalS) {
    const avail = bucket ? bucket.available : executionsAvailable;
    if (!avail) {
      item.health_status = 'unknown';
      item.reason = 'executions_api_unavailable';
      item.fingerprint = `${wid}|unknown_executions`;
      items.push(item); continue;
    }
    if (!latest || !latest.startedAt) {
      // No execution ever — only overdue if expected to have run (interval elapsed since creation unknown).
      // Treat as degraded/unknown without alerting on first observation window for brand-new workflows.
      item.health_status = 'unknown';
      item.reason = 'no_execution_metadata';
      item.fingerprint = `${wid}|no_exec`;
      items.push(item); continue;
    }
    const age = (now.getTime() - new Date(latest.startedAt).getTime()) / 1000;
    const threshold = intervalS * grace;
    if (age > threshold) {
      item.overdue = true;
      item.health_status = (crit === 'critical' || crit === 'high') ? 'failed' : 'degraded';
      item.reason = 'execution_overdue';
      item.event = 'workflow_execution_overdue';
      item.severity = severityFor(crit, item.event);
      item.should_emit = true;
      item.details.age_seconds = Math.round(age);
      item.details.threshold_seconds = Math.round(threshold);
      item.fingerprint = `${wid}|overdue`;
      items.push(item); continue;
    }
  }

  const prev = prevFp[wid || reg.slug];
  if (prev && prev.event && prev.health_status && ['failed','degraded'].includes(prev.health_status)) {
    item.health_status = 'healthy';
    item.reason = 'recovered';
    item.event = prev.event === 'workflow_unexpectedly_inactive' ? 'workflow_reactivated'
      : (prev.event === 'event_bus_unavailable' ? 'event_bus_recovered' : 'workflow_recovered');
    item.severity = 'info';
    item.should_emit = true;
    item.route = item.event === 'event_bus_recovered' ? 'break_glass' : 'event_bus';
    item.fingerprint = `${wid}|recovered|${item.event}`;
    items.push(item); continue;
  }

  item.health_status = 'healthy';
  item.reason = 'ok';
  item.fingerprint = `${wid}|healthy`;
  items.push(item);
}

const severityRank = { info: 1, warning: 2, error: 3, critical: 4 };
for (const item of items) {
  if (!item.should_emit) {
    item.notification = { should_notify: false, reason: 'no_incident' };
    continue;
  }
  const prev = prevFp[item.workflow_id] || prevFp[item.workflow_name];
  if (!prev || !prev.fingerprint) {
    item.notification = { should_notify: true, reason: 'first_incident' };
    continue;
  }
  if (['workflow_recovered','workflow_reactivated','event_bus_recovered'].includes(item.event)) {
    item.notification = { should_notify: true, reason: 'recovered' };
    continue;
  }
  if (item.fingerprint === prev.fingerprint) {
    if ((severityRank[item.severity] || 0) > (severityRank[prev.severity] || 0)) {
      item.notification = { should_notify: true, reason: 'severity_escalated' };
    } else {
      item.should_emit = false;
      item.notification = { should_notify: false, reason: 'no_change' };
    }
    continue;
  }
  item.notification = { should_notify: true, reason: 'incident_changed' };
}

const snapshot = {
  total_registered: items.length,
  expected_active: (REGISTRY.workflows || []).filter(w => w.expected_state === 'active').length,
  healthy: items.filter(i => i.health_status === 'healthy').length,
  degraded: items.filter(i => i.health_status === 'degraded').length,
  failed: items.filter(i => i.health_status === 'failed').length,
  intentionally_inactive: items.filter(i => i.health_status === 'inactive_expected').length,
  blocked: items.filter(i => i.health_status === 'blocked_expected').length,
  unknown: items.filter(i => i.health_status === 'unknown').length,
};
let overall = 'healthy';
if (snapshot.failed || items.some(i => i.event === 'event_bus_unavailable')) overall = 'degraded';
else if (snapshot.degraded || snapshot.unknown) overall = 'attention';

const healthAgentOk = !!(health && (health.status === 'ok' || health.ok === true || health.status === 'healthy' || health.healthy === true || (!health._error && !health.message)));
const duration_ms = Date.now() - started_ms;
const fingerprints = {};
for (const i of items) {
  fingerprints[i.workflow_id || i.workflow_name] = {
    fingerprint: i.fingerprint,
    event: i.event,
    severity: i.severity,
    health_status: i.health_status,
  };
}

const persist = items.map(i => ({ json: { kind: 'persist', checked_at, ...i } }));
const notify = items.filter(i => i.notification && i.notification.should_notify).map(i => {
  const isBreak = i.route === 'break_glass';
  const msg = i.event === 'event_bus_unavailable'
    ? 'BREAK-GLASS: O Hestia Event Bus está inativo. A cadeia de alertas padrão pode estar indisponível.'
    : `Automação OMEAB: ${i.event} — ${i.workflow_name} (${i.reason}).`;
  return { json: {
    kind: 'notify', should_emit: true, route: i.route,
    source: 'omeab_self_health', component: 'automation',
    event: i.event, severity: i.severity, status: i.health_status, timestamp: checked_at,
    message: msg,
    details: {
      workflow_id: i.workflow_id, workflow_name: i.workflow_name, reason: i.reason,
      consecutive_failures: i.consecutive_failures, overdue: i.overdue,
      last_execution_at: i.last_execution_at, last_execution_status: i.last_execution_status,
      notification_reason: i.notification.reason, break_glass_only: isBreak,
    },
    requires_attention: i.severity === 'error' || i.severity === 'critical',
    suggested_action: isBreak
      ? 'Verificar workflow 00 no n8n e entrega Hermes/Telegram. Não há auto-repair.'
      : 'Investigar o workflow indicado. Self Health não reativa nem reexecuta automaticamente.',
    alert: { text: msg },
  }};
});
const metaUpdate = [{ json: {
  kind: 'meta', overall_status: overall,
  last_snapshot: { ...snapshot, overall_status: overall, health_agent_ok: healthAgentOk,
    workflows_api_ok: workflowsOk, executions_available: executionsAvailable, duration_ms, checked_at },
  last_fingerprints: fingerprints,
}}];
return [...persist, ...metaUpdate, ...notify];

const crypto = require('crypto');
const event = $json;
const secret = $env.HESTIA_WEBHOOK_SECRET;
if (!secret) return [{ json: { ...event, break_glass_error: 'HESTIA_WEBHOOK_SECRET missing', skip_break_glass: true } }];
const body = JSON.stringify({ alert: { text: '[BREAK_GLASS_ONLY] ' + (event.alert?.text || event.message || 'automation chain issue') } });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`, 'utf8').digest('hex');
return [{ json: { ...event, hermes_request: { body, timestamp, signature } } }];
